sys_ux_macroponent.props:
[
    {
        "defaultValue": "Submissions to Quote Ratio",
        "description": "Title shown above the value.",
        "fieldType": "string",
        "label": "Heading",
        "name": "heading",
        "valueType": "string"
    },
    {
        "defaultValue": "$",
        "description": "A literal glyph for the icon tile (text or emoji, e.g. $ or %). Always renders identically everywhere (no instance icon-library lookup). Leave empty to hide the icon tile.",
        "fieldType": "string",
        "label": "Icon glyph",
        "name": "iconGlyph",
        "valueType": "string"
    },
    {
        "defaultValue": "25",
        "description": "The headline metric. A number or numeric string; formatted per the Value format property.",
        "fieldType": "string",
        "label": "Value",
        "name": "value",
        "valueType": "string"
    },
    {
        "defaultValue": "percent",
        "description": "How the value is rendered.",
        "fieldType": "choice",
        "label": "Value format",
        "name": "format",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Percent (25.00%)",
                    "value": "percent"
                },
                {
                    "label": "Currency ($25.00)",
                    "value": "currency"
                },
                {
                    "label": "Number (25.00)",
                    "value": "number"
                },
                {
                    "label": "None (as typed)",
                    "value": "none"
                }
            ],
            "schema": {
                "enum": [
                    "percent",
                    "currency",
                    "number",
                    "none"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": 2,
        "description": "Decimal places for the value and trend magnitude.",
        "fieldType": "number",
        "label": "Decimal places",
        "name": "decimals",
        "valueType": "string"
    },
    {
        "defaultValue": "$",
        "description": "Prefix used when Value format is Currency.",
        "fieldType": "string",
        "label": "Currency symbol",
        "name": "currencySymbol",
        "valueType": "string"
    },
    {
        "defaultValue": "-4.2",
        "description": "Change vs the previous period. The sign sets the arrow direction (auto); the magnitude is shown. Leave empty to hide the trend pill.",
        "fieldType": "string",
        "label": "Trend value",
        "name": "trendValue",
        "valueType": "string"
    },
    {
        "defaultValue": "auto",
        "description": "Arrow direction. Auto derives it from the sign of the trend value.",
        "fieldType": "choice",
        "label": "Trend direction",
        "name": "trendDirection",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Auto (from sign)",
                    "value": "auto"
                },
                {
                    "label": "Up",
                    "value": "up"
                },
                {
                    "label": "Down",
                    "value": "down"
                },
                {
                    "label": "Flat",
                    "value": "flat"
                }
            ],
            "schema": {
                "enum": [
                    "auto",
                    "up",
                    "down",
                    "flat"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "MoM",
        "description": "Caption beside the pill, e.g. MoM, YoY, vs last week.",
        "fieldType": "string",
        "label": "Trend period",
        "name": "trendPeriod",
        "valueType": "string"
    },
    {
        "defaultValue": true,
        "description": "When on, an upward trend is green and downward is red. Turn off for lower-is-better metrics (cost, churn, latency).",
        "fieldType": "boolean",
        "label": "Increase is positive",
        "name": "trendPositiveIsGood",
        "valueType": "string"
    },
    {
        "defaultValue": "",
        "description": "Optional CSS color for the icon glyph. Empty uses the theme default.",
        "fieldType": "string",
        "label": "Icon color",
        "name": "iconColor",
        "valueType": "string"
    },
    {
        "defaultValue": "",
        "description": "Optional CSS color for the icon tile background. Empty uses the theme default.",
        "fieldType": "string",
        "label": "Icon background color",
        "name": "iconBackgroundColor",
        "valueType": "string"
    },
    {
        "defaultValue": "center",
        "description": "How the icon tile aligns vertically against the heading/value/trend block.",
        "fieldType": "choice",
        "label": "Icon vertical alignment",
        "name": "iconAlign",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Top",
                    "value": "top"
                },
                {
                    "label": "Center",
                    "value": "center"
                },
                {
                    "label": "Bottom",
                    "value": "bottom"
                }
            ],
            "schema": {
                "enum": [
                    "top",
                    "center",
                    "bottom"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": false,
        "description": "When on, the card is focusable and emits a 'Metric card clicked' event.",
        "fieldType": "boolean",
        "label": "Clickable",
        "name": "clickable",
        "valueType": "string"
    },
    {
        "defaultValue": 12,
        "description": "Corner radius of the card, in pixels. Default 12. The card is clipped to this radius by an owned wrapper.",
        "fieldType": "number",
        "label": "Border radius (px)",
        "name": "borderRadius",
        "valueType": "string"
    }
]
